// n8n -> Convex auth: sha256=HMAC(CONVEX_CALLBACK_SECRET, "<ts>.<METHOD> <path>.<body>"). Body is empty for GET.
const crypto = require('crypto');
const secret = $env.CONVEX_CALLBACK_SECRET;
if (!secret) throw new Error('CONVEX_CALLBACK_SECRET is not set');
const path = '/n8n/overdue-loans';
const ts = String(Math.floor(Date.now() / 1000));
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.GET ${path}.`).digest('hex');
return [{ json: { url: `${$env.CONVEX_SITE_URL}${path}`, headers: { 'X-LendLoop-Timestamp': ts, 'X-LendLoop-Signature': signature } } }];

// One item per overdue loan. Convex decides "today"; the idempotency key is built from its date.
const { date, loans } = $input.first().json;
return loans.map((l) => {
  const days = l.daysOverdue === 1 ? '1 day' : `${l.daysOverdue} days`;
  return {
    json: {
      loanId: l.loanId,
      date,
      idempotencyKey: `reminder:${l.loanId}:${date}`,
      to: l.borrower.email,
      subject: `LendLoop: please return the ${l.tool.name}`,
      text: `Hi ${l.borrower.firstName},\n\nThe ${l.tool.name} you borrowed was due back on ${l.endDate} (${days} ago). Please return it to its owner so they can mark it returned in LendLoop.\n\nThanks for keeping the loop going!\n\n- LendLoop`,
    },
  };
});

// Runs once per loan. A failed email still gets a write-back (status "failed") so admins see it.
const crypto = require('crypto');
const secret = $env.CONVEX_CALLBACK_SECRET;
if (!secret) throw new Error('CONVEX_CALLBACK_SECRET is not set');

const reminder = $('Prepare reminders').item.json;
const failed = Boolean($json.error);
const error = failed ? String($json.error?.message ?? $json.error).slice(0, 500) : undefined;
const body = JSON.stringify({
  loanId: reminder.loanId,
  date: reminder.date,
  status: failed ? 'failed' : 'sent',
  idempotencyKey: reminder.idempotencyKey,
  ...(failed ? { error } : {}),
});

const path = '/n8n/reminder-status';
const ts = String(Math.floor(Date.now() / 1000));
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.POST ${path}.${body}`).digest('hex');
return {
  json: {
    url: `${$env.CONVEX_SITE_URL}${path}`,
    body,
    headers: { 'X-LendLoop-Timestamp': ts, 'X-LendLoop-Signature': signature },
    loanId: reminder.loanId,
    emailStatus: failed ? 'failed' : 'sent',
  },
};

// Every loan has been processed by now. If any email or write-back failed, fail the run so the
// error workflow (LendLoop 7) alerts someone; the rest of the loans were still handled.
const results = $input.all().map((item, i) => {
  const sent = $('Sign write-back').itemMatching(i).json;
  return { loanId: sent.loanId, email: sent.emailStatus, writeBack: item.json.error ? 'failed' : item.json.outcome };
});
const problems = results.filter((r) => r.email === 'failed' || r.writeBack === 'failed');
if (problems.length > 0) {
  throw new Error(`Overdue reminders: ${problems.length} of ${results.length} loans had problems: ${JSON.stringify(problems)}`);
}
return [{ json: { reminded: results.length, results } }];
